// Writes site/src/css/oxygen-tokens.css from @wso2/oxygen-ui's WSO2Theme: the package is the source of the site's look,
// read at build time only (it is not tree-shakeable, so browser code never imports it; wso2/oxygen-ui#578).
//
//   node scripts/oxygen-tokens.mjs            regenerate the file
//   node scripts/oxygen-tokens.mjs --check    fail when the committed file differs (CI, or after an Oxygen upgrade)
//
// Upgrading Oxygen: bump the exact pin, run without --check, review the diff of the generated file.
import fs from 'node:fs';
import path from 'node:path';
import { register } from 'node:module';
import { fileURLToPath } from 'node:url';

// The package imports Prism files without extensions and CSS files; Node needs both resolved for a plain import.
register('data:text/javascript,' + encodeURIComponent(`
export async function resolve(spec, ctx, next) {
  try { return await next(spec, ctx); } catch (e) { if (e.code === 'ERR_MODULE_NOT_FOUND' && !spec.endsWith('.js')) return next(spec + '.js', ctx); throw e; }
}
export async function load(url, ctx, next) {
  if (url.endsWith('.css')) return { format: 'module', source: 'export default {}', shortCircuit: true };
  return next(url, ctx);
}`));

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const OUT = path.join(ROOT, 'site/src/css/oxygen-tokens.css');
const { WSO2Theme: theme } = await import('@wso2/oxygen-ui');
const { version } = JSON.parse(fs.readFileSync(path.join(ROOT, 'node_modules/@wso2/oxygen-ui/package.json'), 'utf8'));

/** "r g b" for a hex or rgb() colour, or null. */
function channel(value) {
  const hex = /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(value);
  if (hex) {
    const h = hex[1].length === 3 ? [...hex[1]].map((c) => c + c).join('') : hex[1];
    return [0, 2, 4].map((i) => parseInt(h.slice(i, i + 2), 16)).join(' ');
  }
  const rgb = /^rgba?\(\s*(\d+)[\s,]+(\d+)[\s,]+(\d+)/i.exec(value);
  return rgb ? rgb.slice(1, 4).join(' ') : null;
}

/** Infima's primary scale (as the Docusaurus colour generator makes it): lightness scaled in HSL. */
function scale(hex) {
  const [r, g, b] = channel(hex).split(' ').map((n) => n / 255);
  const max = Math.max(r, g, b), min = Math.min(r, g, b), l = (max + min) / 2, d = max - min;
  const s = d === 0 ? 0 : d / (1 - Math.abs(2 * l - 1));
  const h = d === 0 ? 0 : max === r ? ((g - b) / d) % 6 : max === g ? (b - r) / d + 2 : (r - g) / d + 4;
  const toHex = (light) => {
    const c = (1 - Math.abs(2 * light - 1)) * s, x = c * (1 - Math.abs((h % 2 + 2) % 2 - 1)), m = light - c / 2;
    const [r1, g1, b1] = h < 1 ? [c, x, 0] : h < 2 ? [x, c, 0] : h < 3 ? [0, c, x] : h < 4 ? [0, x, c] : h < 5 ? [x, 0, c] : [c, 0, x];
    return '#' + [r1, g1, b1].map((v) => Math.round((v + m) * 255).toString(16).padStart(2, '0')).join('');
  };
  const at = (k) => toHex(Math.min(1, Math.max(0, l * (1 + k)))); // color's darken/lighten: lightness ± lightness × k
  return { '': hex, '-dark': at(-0.1), '-darker': at(-0.15), '-darkest': at(-0.3), '-light': at(0.1), '-lighter': at(0.15), '-lightest': at(0.3) };
}

const fixed = [];
/** One block of declarations: channel values recomputed from their colour (Oxygen 0.16 emits wrong ones), and values
 * holding `undefined` dropped. */
function block(selector, vars) {
  const lines = [];
  for (const [name, raw] of Object.entries(vars)) {
    if (!name.startsWith('--')) continue;
    let value = String(raw);
    if (value.includes('undefined')) { fixed.push(`${name}: dropped (${value})`); continue; }
    if (name.endsWith('Channel') && vars[name.slice(0, -'Channel'.length)] !== undefined) {
      const right = channel(String(vars[name.slice(0, -'Channel'.length)]));
      if (right && right !== value) { fixed.push(`${name}: ${value} -> ${right}`); value = right; }
    }
    lines.push(`  ${name}: ${value};`);
  }
  return `${selector} {\n${lines.join('\n')}\n}`;
}

const [base, light, dark] = theme.generateStyleSheets().map((s) => Object.entries(s)[0]);
const type = theme.typography;
const typeVars = {};
for (const k of ['h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'body1', 'body2', 'caption']) {
  const t = type[k];
  if (!t) continue;
  typeVars[`--oxygen-typography-${k}-fontSize`] = t.fontSize;
  typeVars[`--oxygen-typography-${k}-fontWeight`] = t.fontWeight;
  typeVars[`--oxygen-typography-${k}-lineHeight`] = t.lineHeight;
}
typeVars['--oxygen-typography-fontFamily'] = type.fontFamily;

// Link text in light mode uses primary.dark: primary.main (#FF7300) on white fails WCAG AA as text (map decision).
const primaryLight = String(light[1]['--oxygen-palette-primary-dark']);
const primaryDark = String(dark[1]['--oxygen-palette-primary-main']);
const infima = (shades) => Object.entries(shades).map(([k, v]) => `  --ifm-color-primary${k}: ${v};`).join('\n');

const css = `/* GENERATED by scripts/oxygen-tokens.mjs from @wso2/oxygen-ui ${version} (WSO2Theme). Do not edit; regenerate. */

${block(base[0], { ...base[1], ...typeVars })}

${block(':root, [data-color-scheme="light"]', light[1])}

${block('[data-color-scheme="dark"], [data-theme="dark"]', dark[1])}

/* Infima primary scale: light mode from primary.dark (contrast), dark mode from primary.main. */
:root {
${infima(scale(primaryLight.startsWith('#') ? primaryLight : '#' + channel(primaryLight).split(' ').map((n) => Number(n).toString(16).padStart(2, '0')).join('')))}
}
[data-theme="dark"] {
${infima(scale(primaryDark))}
}
`;

if (process.argv.includes('--check')) {
  const now = fs.existsSync(OUT) ? fs.readFileSync(OUT, 'utf8') : '';
  if (now !== css) { console.error(`${path.relative(ROOT, OUT)} is out of date: run node scripts/oxygen-tokens.mjs`); process.exit(1); }
  console.log('oxygen tokens up to date');
} else {
  fs.writeFileSync(OUT, css);
  console.log(`wrote ${path.relative(ROOT, OUT)} from @wso2/oxygen-ui ${version}; corrected ${fixed.length} values:`);
  for (const f of fixed) console.log(`  ${f}`);
}
